effect.shader:
#define PI 3.14159265359
mat2 rot2m(float a) {
float s = sin(a);
float c = cos(a);
return mat2(c, -s, s, c);
}
void main () {
vec2 uv = acScreenNorm;
vec4 texColor = texture2DCv(inputImg.texture, uv);
float baseAlpha = texColor.a;
vec2 st = ((vec2(uv.x, 1.0 - uv.y) * acScreenSize) - acLayerCenter) / acLayerSize;
st.y *= acLayerSize.y / max(acLayerSize.x, 1.0);
st /= scaleNorm ? (scale + 0.7) : (scale - 0.82 + 0.001);
st *= rot2m(angle * 0.0174532925);
st += vec2(position.x, position.y) * vec2(-1.0, 1.0) / 500.0;
vec2 scaleVec = vec2(scale * stretch.x, scale * stretch.y);
st /= max(scaleVec, vec2(0.001));
vec2 center = st;
float len = max(length(center), 0.0001);
float a = 1.0 / len + atan(center.x, center.y) / PI * amplitude + evolution;
float b = sin(a * PI * 8.0) * dot(center, center) * acScreenSize.y / (depth + 300.0) - 0.3;
float c = b * sin(len - 0.1);
vec4 lineT = mix(colorBG, colorLine, clamp(c, 0.0, 1.0));
vec4 factor = lineT;
vec4 resultfinal;
vec3 tcSafe = texColor.rgb / max(texColor.a, 0.001);
if (blendMode == 0) {
resultfinal = factor * brightness;
} else if (blendMode == 1) {
factor *= brightness;
vec3 mixed = factor.rgb + vec3(1.0) * (1.0 - factor.a);
resultfinal = vec4(tcSafe * mixed, 1.0);
} else if (blendMode == 2) {
factor *= brightness;
resultfinal = vec4(1.0 - ((1.0 - tcSafe) * (1.0 - factor.rgb)), 1.0);
}
resultfinal = clamp(resultfinal, 0.0, 1.0);
resultfinal.rgb *= baseAlpha;
resultfinal.a = baseAlpha;
vec4 outputColor = mix(texColor, resultfinal, alpha * factor.a);
gl_FragColor = outputColor;
}
